    // an otherwise useful open-bin slot.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * open_bins_count as f64;
        score += 6.0 * (capacity - item) / capacity;
    } else {
        // Prefer tighter fits, with a nonlinear bonus for avoiding substantial
        // residual space that can become stranded in a long stream.
        let tightness = if residual > 0.0 {
            1.0 - (residual - item).max(0.0) / residual
        } else {
            0.0
        };
        score -= 24.0 * tightness;
        score += 0.45 * post_residual as f64;

