            score += 5.0 * deficit * deficit / capacity;
        }

        // Relative residual pressure: bins below the stream mean are more
        // valuable when the next item is large, while unusually roomy bins
        // should not be selected merely because they are still empty.
        let mean_gap = mean - post_residual as f64;
        score -= 0.65 * mean_gap;
