    let post_ratio = post_residual as f64 / capacity;
    let item_ratio = item_size as f64 / capacity;
    let mean_ratio = (mean_residual / capacity).clamp(0.0, 1.0);
    let scarcity = if fitting_bins_count == 0 {
        1.0
    } else {
        1.0 / (fitting_bins_count as f64)
    };
    let lookahead_ratio = if next_item_size == 0 {
        0.0
    } else {
        next_item_size as f64 / capacity
    };
    let progress_curve = progress * progress * (3.0 - 2.0 * progress);
    let dead_space = post_ratio * post_ratio;
    let fragmentation = (post_ratio - mean_ratio) * (post_ratio - mean_ratio);
    let new_bin_penalty = if bin_residual == bin_capacity {
        18.0 + 12.0 * progress_curve + 8.0 * scarcity
    } else {
        0.0
    };
    let urgency = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
    let coverage_penalty = 10.0 * (1.0 - scarcity);
    let size_fit_term = -3.0 * item_ratio * residual_ratio;
    let next_fit_term = 4.0 * lookahead_ratio * post_ratio * progress_curve;
