        + 90.0 * fragmentation
        + new_bin_penalty
        + urgency
        + coverage_penalty
        + size_fit_term
        + next_fit_term
        + 6.0 * open_bins_count as f64 * (1.0 - post_ratio) / (1.0 + progress_curve);
