pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    let item = item_size as f64;
    let capacity = bin_capacity as f64;
    let residual = bin_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    let occupancy = if capacity > 0.0 {
        (capacity - residual) / capacity
    } else {
        0.0
    };

    // Prefer compact placements, but preserve enough room for a likely next item.
    let space_efficiency = residual / capacity.max(1.0);
    let dead_space_penalty = if post_residual > 0 && post_residual < item {
        0.35 * post_residual as f64
    } else {
        0.0
    };
    score += 9.0 * space_efficiency + dead_space_penalty;

    if next > 0.0 {
        let next_fits = if post_residual >= next_item_size {
            1.0
        } else {
            0.0
        };
        let next_need = (next - post_residual as f64).max(0.0);
        score -= 4.5 * next_fits;
        score += 0.12 * next_need;

        // A large upcoming item makes residual fragmentation more costly.
        let pressure = (next / capacity.max(1.0)).clamp(0.0, 1.0);
        score += pressure * 2.5 * (1.0 - occupancy);
    }

    // Fit into the best remaining space instead of creating another almost-empty bin.
    if fitting_bins_count == 1 && residual < capacity {
        score -= 7.0;
    }
    if fitting_bins_count > 1 {
        score -= 1.5;
    }

    // Favor bins whose residual is close to the global residual profile.
    let residual_gap = (residual - mean_residual).abs();
    score += 0.035 * residual_gap;

    // Early in a long stream, preserve flexible capacity; later, prioritize consolidation.
    let horizon = (1.0 - progress).clamp(0.0, 1.0);
    score += horizon * 1.8 * (post_residual as f64 / capacity.max(1.0));

    // Opening a new bin is attractive only when this candidate is empty and existing bins
    // offer substantially better opportunities, or when the stream is near its end.
    if bin_residual == bin_capacity {
        score += if open_bins_count == 0 { -8.0 } else { 3.0 };
        score += 4.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);
    }

    score
}
